function minStoneSum(piles, k) {
  // A max-heap in an array: each parent is at least as large as its children.
  const heap = [...piles];
  const siftDown = start => {
    let parent = start;
    for (;;) {
      let largest = parent;
      const left = 2 * parent + 1;
      const right = left + 1;
      if (left < heap.length && heap[left] > heap[largest]) {
        largest = left;
      }
      if (right < heap.length && heap[right] > heap[largest]) {
        largest = right;
      }
      if (largest === parent) {
        return;
      }
      [heap[parent], heap[largest]] = [heap[largest], heap[parent]];
      parent = largest;
    }
  };
  for (let i = (heap.length >> 1) - 1; i >= 0; i--) {
    siftDown(i);
  }

  let total = piles.reduce((sum, pile) => sum + pile, 0);
  for (let move = 0; move < k; move++) {
    const removed = Math.floor(heap[0] / 2);
    if (removed === 0) {
      break;
    }
    heap[0] -= removed;
    total -= removed;
    siftDown(0);
  }
  return total;
}

