function minStoneSum(piles, k) {
  // Try every sequence of moves, remembering results for states already seen.
  const memo = new Map();
  const best = (state, movesLeft) => {
    if (movesLeft === 0 || state.every(v => v === 1)) return state.reduce((a, b) => a + b, 0);
    const key = state.join(',') + '|' + movesLeft;
    if (memo.has(key)) return memo.get(key);
    let answer = Infinity;
    for (let i = 0; i < state.length; i++) {
      const next = state.slice();
      next[i] = Math.ceil(next[i] / 2);
      answer = Math.min(answer, best(next, movesLeft - 1));
    }
    memo.set(key, answer);
    return answer;
  };
  return best(piles.slice(), k);
}

