function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const piles = Array.from({ length: 2000 }, () => int(1, 10000));
    return [piles, int(1, 100000)];
  }
  const n = int(1, 5);
  const top = rand() < 0.2 ? 10000 : int(1, 40);
  const piles = Array.from({ length: n }, () => int(1, top));
  return [piles, int(1, 7)];
}
